;; curriculum: Calc-2 (undergrad) — geometric series; prerequisites: doubling, tail
;; math target: 1 + 1/2 + 1/4 + … converges to 2; the partial sums creep toward the ceiling.

app riya-level-series "1.1.0"
"riya level 12 · Series — geometric series and limits. Hop up the halving staircase 1 + ½ + ¼ + … toward the ceiling 2, then choose the limit to cross the final gap. Catch 5 ★! Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas so the steps, hops, and ceiling stay visible. Rebound into the riya-game-platformer organism (menu + all worlds)."

;; @exposure internal

orbital RiyaSeriesOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaSeriesBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaSeriesPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaSeriesFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaSeriesCurveSample = {
    x : number!
    y : number!
  }
  type RiyaSeriesCurve = {
    label : string
    color : string
    samples : [RiyaSeriesCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaSeriesGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaSeriesHop = {
    from : number!
    to : number!
    label : string!
    color : string
  }
  type RiyaSeriesPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaSeriesChoiceOption = {
    id : string!
    dx : number!
    label : string!
    correct : boolean!
  }
  type RiyaSeriesChoiceGate = {
    id : string!
    x : number!
    y : number!
    hint : string
    options : [RiyaSeriesChoiceOption]!
  }
  type RiyaSeriesFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  entity RiyaSeriesState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaSeriesBody = { x: -9, y: 2.2, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaSeriesPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaSeriesFx] = []
    celebrated : boolean = false
    zoneId : string = "series"
    platforms : [RiyaSeriesPlatform] = []
    curves : [RiyaSeriesCurve] = []
    guides : [RiyaSeriesGuide] = []
    hops : [RiyaSeriesHop] = []
    choiceGates : [RiyaSeriesChoiceGate] = []
    ceilingStars : [RiyaSeriesPickup] = []
  }

  entity SeriesTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait SeriesBody = Body.traits.PlatformerBody -> RiyaSeriesState {
    events {
      STEER: SERIES_STEER
      JUMP: SERIES_LEAP
      PLACE: SERIES_PLACE
      RESTART: SERIES_RESTART
      CURVE_MOD_ADD: SERIES_CURVE_MOD_ADD
      SET_TUNING: SERIES_SET_TUNING
      SET_PLATFORMS: SERIES_SET_PLATFORMS
      SET_SKATE_CURVE: SERIES_SET_SKATE_CURVE
      BODY_JUMPED: SERIES_JUMPED
      BODY_LANDED: SERIES_LANDED
      BODY_HAZARD: SERIES_HAZARD
      BODY_GOAL: SERIES_GOAL
      BODY_FELL: SERIES_FELL
      BODY_SKATE_START: SERIES_SKATE_ON
      BODY_SKATE_END: SERIES_SKATE_OFF
    }
    config {
      running: true
      spawn: { x: -9, y: 2.2, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      skateSnap: 0.9
    }
  }

  trait SeriesGate = Gate.traits.ObjectiveFlow -> RiyaSeriesState {
    events {
      PROGRESS: SERIES_PROGRESS
      GAME_END: SERIES_GAME_END
      RESTART: SERIES_RESTART
    }
    config { running: true }
  }

  trait SeriesFx = Particles.traits.FxParticles -> RiyaSeriesState {
    events {
      BURST: SERIES_BURST
    }
    config { running: true }
  }

  trait SeriesTutorialPreview -> SeriesTutorialData [interaction, instance] {
    initial: idle
    state idle {
      INIT -> idle
        (render-ui center null)
    }
  }

  trait SeriesTutorial = Tutorial.traits.TutorialOverlay -> SeriesTutorialData {
    events {
      SHOW: SERIES_TUTORIAL_SHOW
      TUTORIAL_DONE: SERIES_TUTORIAL_DONE
    }
    config {
      autoShow: true
      previewTrait: @trait.SeriesTutorialPreview
      steps: [
        { id: "intro", title: "Series", body: "Each step is half the previous: 1 + ½ + ¼ + … The staircase rises toward the ceiling S = 2 but never crosses it. Choose the limit to reach the final star." }
      ]
    }
  }

  trait SeriesPickup = Pickup.traits.Pickup -> RiyaSeriesState {
    events {
      PICKED: SERIES_PICKED
      COLLECT: SERIES_COLLECT
      PICKUP_SET_COMPLETED: SERIES_PICKUP_SET_COMPLETED
      SET_FEATURES: SERIES_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait SeriesLevelData -> @rebindable RiyaSeriesState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "series"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn c @c))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          hops: (array/map @config.hops (fn h @h))
          choiceGates: (array/map @config.choiceGates (fn g @g))
          ceilingStars: (array/map @config.ceilingStars (fn s @s))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaSeriesPlatform]!
        stars : [RiyaSeriesPickup]!
        skateCurve : [RiyaSeriesCurveSample]
        curveOverlay : [RiyaSeriesCurve]
        guides : [RiyaSeriesGuide]
        hops : [RiyaSeriesHop]
        choiceGates : [RiyaSeriesChoiceGate]
        ceilingStars : [RiyaSeriesPickup]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "Series"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "S = 2"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "geometric series 1 + ½ + ¼ + … approaches the ceiling 2; the hops shrink by half each step; the limit gate asks for the unreachable sum"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#38bdf8"
        @label "Region Color"
        @description "Zone band accent in the open world."
        @tier "presentation"
      entryY : number = 1
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge; the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 1.99609375
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge; the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaSeriesPlatform] = [
        { id: "b0", x: -9.6, y: -2, width: 1.6, height: 3, type: "ground" }
        { id: "b1", x: -8, y: -2, width: 1.6, height: 3.5, type: "ground" }
        { id: "b2", x: -6.4, y: -2, width: 1.6, height: 3.75, type: "ground" }
        { id: "b3", x: -4.8, y: -2, width: 1.6, height: 3.875, type: "ground" }
        { id: "b4", x: -3.2, y: -2, width: 1.6, height: 3.9375, type: "ground" }
        { id: "b5", x: -1.6, y: -2, width: 1.6, height: 3.96875, type: "ground" }
        { id: "b6", x: 0, y: -2, width: 1.6, height: 3.984375, type: "ground" }
        { id: "b7", x: 1.6, y: -2, width: 1.6, height: 3.9921875, type: "ground" }
        { id: "b8", x: 3.2, y: -2, width: 1.6, height: 3.99609375, type: "ground" }
        { id: "opt-1", x: 5.6, y: -2, width: 1.6, height: 4, type: "hazard" }
        { id: "opt-2", x: 7.2, y: -2, width: 1.6, height: 4, type: "platform" }
        { id: "opt-inf", x: 8.8, y: -2, width: 1.6, height: 4, type: "hazard" }
      ]
        @label "Platforms"
