  trait RiyaSeriesGenre = Genre.traits.PlatformerPuzzle -> RiyaSeriesState {
    config {
      agencyTrait: @trait.SeriesBody
      challengeTrait: @trait.SeriesBody
      goalTrait: @trait.SeriesGate
      rewardTrait: @trait.SeriesPickup
      feedbackTrait: @trait.SeriesFx
    }
  }

  trait RiyaSeriesPlay -> @rebindable RiyaSeriesState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit SERIES_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "SERIES_LEFT", KeyA: "SERIES_LEFT", ArrowRight: "SERIES_RIGHT", KeyD: "SERIES_RIGHT", ArrowUp: "SERIES_JUMP", KeyW: "SERIES_JUMP", Space: "SERIES_JUMP" }
            keyUpMap: { ArrowLeft: "SERIES_STOP", KeyA: "SERIES_STOP", ArrowRight: "SERIES_STOP", KeyD: "SERIES_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            guides: @entity.guides
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: (if (== (object/get @p type) "hazard") "#ef4444" @config.terrainColor), opacity: 0.85 }))
            hops: (array/map @entity.hops (fn h { from: (object/get @h from), to: (object/get @h to), label: (object/get @h label), color: (object/get @h color) }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              (array/concat
                (array/map @entity.choiceGates (fn g
                  (array/map (object/get @g options) (fn o
                    { x: (+ (object/get @g x) (object/get @o dx)), y: (+ (object/get @g y) 0.4), label: (object/get @o label), color: (if (== (object/get @o correct) true) "#22c55e" "#ef4444"), radius: 10 }))))
                (array/concat
                  @entity.ceilingStars
                  (array/concat
                    [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                    (array/concat
                      (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                      (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] []))))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "SERIES_LEFT", right: "SERIES_RIGHT", up: "SERIES_JUMP" }, directionReleaseEvents: { left: "SERIES_STOP", right: "SERIES_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "series")
        (set @entity.curves @payload.curveOverlay)
        (set @entity.guides @payload.guides)
        (set @entity.hops @payload.hops)
        (set @entity.choiceGates @payload.choiceGates)
        (set @entity.ceilingStars @payload.ceilingStars)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit SERIES_SET_PLATFORMS { platforms: @payload.platforms })
        (emit SERIES_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit SERIES_SET_FEATURES { features: @payload.stars })

      SERIES_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit SERIES_STEER { dir: -1 })

      SERIES_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit SERIES_STEER { dir: 1 })

      SERIES_STOP -> idle when (== @entity.active true)
        (emit SERIES_STEER { dir: 0 })

      SERIES_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit SERIES_LEAP {})

      SERIES_FELL -> idle when (== @entity.active true)
        (emit SERIES_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit SERIES_BURST { particles: (array/map [ "fx-series-fell" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "💫", ttl: 3 })) })

      SERIES_SKATE_ON -> idle when (== @entity.active true)
        (emit SERIES_BURST { particles: (array/concat
          { id: "narrative-skate", type: "narrative", x: @entity.body.x, z: (+ @entity.body.y 2), y: 0, message: "each step is half the last", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
          {
            id: "fx-series-skate",
            type: "info",
            x: @payload.x,
            z: (+ @payload.y 0.6),
            y: 0,
            message: (str/concat @config.equationText " · x = " (math/round (+ @payload.x 0.3) 1)),
            ttl: 4
          }
        ) })
      SERIES_PICKED -> idle when (== @entity.active true)
        (emit SERIES_BURST { particles: (array/map [ "fx-pickup-" ] (fn fid { id: (str/concat @fid @payload.id), type: "pickup", x: @payload.x, z: @payload.y, message: @payload.glyph, ttl: 2 })) })
      SERIES_COLLECT -> idle when (== @entity.active true)
        (set @entity.score @payload.total)
        (set @entity.objectivesLeft (- (array/len @entity.pickups) @payload.total))
        (emit SERIES_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })

      SERIES_PICKUP_SET_COMPLETED -> idle when (== @entity.active true)
        (emit SERIES_BURST { particles: (array/map [ "complete" ] (fn _ { id: "narrative-complete", type: "narrative", x: 0, z: 8, y: 0, message: "the sum converges to 2", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
        (emit SERIES_PROGRESS { objectivesLeft: 0, movesLeft: 9999 })
      SERIES_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "series" })

      SERIES_TUTORIAL_DONE -> idle
        (emit SERIES_BURST { particles: (array/map [ "tutorial" ] (fn _ { id: "narrative-tutorial", type: "narrative", x: 0, z: 10, y: 0, message: "1 + ½ + ¼ + … creeps toward 2", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
    }

    ticks {
      renderTick every 100ms when (== @entity.active true)
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "SERIES_LEFT", KeyA: "SERIES_LEFT", ArrowRight: "SERIES_RIGHT", KeyD: "SERIES_RIGHT", ArrowUp: "SERIES_JUMP", KeyW: "SERIES_JUMP", Space: "SERIES_JUMP" }
            keyUpMap: { ArrowLeft: "SERIES_STOP", KeyA: "SERIES_STOP", ArrowRight: "SERIES_STOP", KeyD: "SERIES_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            guides: @entity.guides
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: (if (== (object/get @p type) "hazard") "#ef4444" @config.terrainColor), opacity: 0.85 }))
            hops: (array/map @entity.hops (fn h { from: (object/get @h from), to: (object/get @h to), label: (object/get @h label), color: (object/get @h color) }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              (array/concat
                (array/map @entity.choiceGates (fn g
                  (array/map (object/get @g options) (fn o
                    { x: (+ (object/get @g x) (object/get @o dx)), y: (+ (object/get @g y) 0.4), label: (object/get @o label), color: (if (== (object/get @o correct) true) "#22c55e" "#ef4444"), radius: 10 }))))
                (array/concat
                  @entity.ceilingStars
                  (array/concat
                    [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                    (array/concat
                      (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                      (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] []))))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
    }

    emits {
      SERIES_LEFT -> external {
        id : string
      }
        @description "Run-left intent from ArrowLeft/KeyA keydown or d-pad (forwarded as STEER dir −1)."
        @tier "domain"
      SERIES_RIGHT -> external {
        id : string
      }
        @description "Run-right intent from ArrowRight/KeyD keydown or d-pad (forwarded as STEER dir +1)."
        @tier "domain"
      SERIES_STOP -> external {
        id : string
      }
        @description "Left/right key release (keyUpMap or d-pad release); forwarded as STEER dir 0."
        @tier "domain"
      SERIES_JUMP -> external {
        id : string
      }
        @description "Jump intent from Space/ArrowUp/KeyW or d-pad up; forwarded as the body authority's renamed JUMP (SERIES_LEAP), which accepts it only while grounded."
        @tier "domain"
      SERIES_STEER -> external {
        dir : number!
      }
        @description "Renamed STEER consumed by this world's platformer-body authority (−1/0/+1 × moveSpeed)."
        @tier "domain"
      SERIES_LEAP -> external {
        id : string
      }
        @description "Renamed JUMP consumed by this world's platformer-body authority (grounded-gated vertical kick)."
        @tier "domain"
      SERIES_PLACE -> external {
        x : number!
        y : number!
      }
        @description "Renamed PLACE consumed by this world's platformer-body authority; the pit-fall/hazard respawn teleport."
        @tier "domain"
      SERIES_FELL -> external {
        x : number!
        y : number!
      }
        @description "Pit-fall signal from this world's platformer-body authority (renamed BODY_FELL); respawns riya at her spawn with every star kept."
        @tier "domain"
      SERIES_SKATE_ON -> external {
        x : number!
        y : number!
        slope : number!
      }
        @description "Skate-engage signal from this world's platformer-body authority (renamed BODY_SKATE_START); riya touched the ceiling line — fires the equation fx burst."
        @tier "domain"
      SERIES_PICKED -> external {
        id : string!
        kind : string!
        x : number!
        y : number!
        glyph : string
        message : string
      }
        @description "A pickup was collected (renamed PICKED from std-pickup)."
        @tier "domain"
      SERIES_COLLECT -> external {
        total : number!
      }
        @description "Running pickup count (renamed COLLECT from std-pickup); updates score/objectives and forwards to the objective-flow gate."
        @tier "domain"
      SERIES_PICKUP_SET_COMPLETED -> external {
      }
        @description "Every pickup in the set is collected (renamed PICKUP_SET_COMPLETED from std-pickup)."
        @tier "domain"
      SERIES_CURVE_MOD_ADD -> external {
        x0 : number!
        x1 : number!
        a : number!
        h : number!
        k : number!
      }
        @description "Renamed CURVE_MOD_ADD consumed by the platformer-body authority; applies a lift/tilt mod to the skate curve."
        @tier "domain"
      SERIES_SET_TUNING -> external {
        jumpStrength : number
        moveSpeed : number
        gravity : number
      }
        @description "Renamed SET_TUNING consumed by the platformer-body authority; applies live body tuning overrides."
        @tier "domain"
      SERIES_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's platformer-body/objective-flow/pickup authorities (renamed RESTART)."
        @tier "domain"
      SERIES_BURST -> external {
        particles : [RiyaSeriesFx]
      }
        @description "Particle batch spawned on star pickup, boost pickup, pit respawn, or hazard respawn; fx-particles fades it."
        @tier "domain"
      SERIES_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted by the gameTick only when a star is collected; the objective-flow gate resolves won from it."
        @tier "domain"
      SERIES_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won clears the level."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
      SERIES_SET_PLATFORMS -> external {
        platforms : [RiyaSeriesPlatform]!
      }
        @description "Renamed SET_PLATFORMS consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA terrain to collision."
        @tier "domain"
      SERIES_SET_SKATE_CURVE -> external {
        curve : [RiyaSeriesCurveSample]!
      }
        @description "Renamed SET_SKATE_CURVE consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA skate path."
        @tier "domain"
      SERIES_SET_FEATURES -> external {
        features : [RiyaSeriesPickup]!
      }
        @description "Renamed SET_FEATURES consumed by this world's pickup authority; forwards the canonical RIYA_LEVEL_DATA stars."
        @tier "domain"
    }

    listens {
      SERIES_TUTORIAL_DONE { id : string }
      RIYA_LEVEL_DATA {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaSeriesPlatform]!
        stars : [RiyaSeriesPickup]!
        skateCurve : [RiyaSeriesCurveSample]
        curveOverlay : [RiyaSeriesCurve]
        guides : [RiyaSeriesGuide]
        hops : [RiyaSeriesHop]
        choiceGates : [RiyaSeriesChoiceGate]
        ceilingStars : [RiyaSeriesPickup]
      }
    }

    config {
      equationText : string = "S = 2"
        @label "Equation Text"
        @description "Equation of this world's curve, shown by the skate fx burst and the floating label that follows riya while she skates the graph."
        @tier "presentation"
      equationColor : string = "#7dd3fc"
        @label "Equation Color"
        @description "Color of the floating equation label that follows riya while she skates."
        @tier "presentation"
      curveSkateColor : string = "#f0abfc"
        @label "Curve Skate Color"
        @description "Curve trace color while riya is skating the graph (the faint curveOverlay color otherwise)."
        @tier "presentation"
      respawnX : number = -9
        @label "Respawn X"
        @description "X riya teleports to after a pit fall or wrong choice (matches SeriesBody spawn.x)."
        @tier "domain"
      respawnY : number = 2.2
        @label "Respawn Y"
        @description "Y riya teleports to after a pit fall or wrong choice (matches SeriesBody spawn.y)."
        @tier "domain"
      reachRadius : number = 0.7
        @label "Reach Radius"
        @description "Manhattan distance from riya's center at which the gameTick counts a star as collected."
        @tier "domain"
      objectiveText : string = ""
