  trait SeriesChallenge -> @rebindable RiyaSeriesState [game-core, instance] {
    initial: idle

    state idle {
      SERIES_HAZARD -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (emit SERIES_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit SERIES_BURST { particles: (array/map [ "fx-series-hazard" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "✗", ttl: 3 })) })

      SERIES_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (str/endsWith @payload.id "term-1")
          (emit SERIES_BURST { particles: [ { id: "narrative-term", type: "narrative", x: @payload.x, z: (+ @payload.y 2), y: 0, message: "r = ½", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 } ] })
          null)
    }

    emits {
      SERIES_PLACE -> external {
        x : number!
        y : number!
      }
        @description "Renamed PLACE consumed by this world's platformer-body authority; the wrong-limit-option hazard respawn teleport."
        @tier "domain"
      SERIES_BURST -> external {
        particles : [RiyaSeriesFx]
      }
        @description "Particle batch spawned on hazard respawn or the r = ½ term-pad narrative beat; fx-particles fades it."
        @tier "domain"
    }

    listens {
      SERIES_HAZARD { id : string! }
      SERIES_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "series"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
      respawnX : number = -9
        @label "Respawn X"
        @description "X riya teleports to after a wrong limit choice (matches SeriesBody spawn.x)."
        @tier "domain"
      respawnY : number = 2.2
        @label "Respawn Y"
        @description "Y riya teleports to after a wrong limit choice (matches SeriesBody spawn.y)."
        @tier "domain"
    }
  }

  trait RiyaSeriesClear -> @rebindable RiyaSeriesState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "SERIES_NEXT", variant: "primary" } ]
        })

      SERIES_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      SERIES_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-series"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Series clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "Every step half the previous: the sum 1 + ½ + ¼ + … piles up to exactly 2."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-series" as RiyaSeriesPage -> SeriesLevelData, SeriesBody, SeriesGate, SeriesFx, SeriesPickup, SeriesTutorial, RiyaSeriesGenre, RiyaSeriesPlay, SeriesChallenge, RiyaSeriesClear
}
